CREATE TABLE IF NOT EXISTS survey_responses (id TEXT PRIMARY KEY, edit_token_hash TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, survey_version TEXT NOT NULL, main_answers TEXT NOT NULL, extra_answers TEXT, free_text TEXT, top_priorities TEXT, absolute_priority TEXT, budget_monthly TEXT, budget_purchase TEXT, extra_status TEXT NOT NULL DEFAULT 'not_started' CHECK (extra_status IN ('not_started','declined','completed')), extra_completed_at TEXT); CREATE INDEX IF NOT EXISTS idx_survey_created ON survey_responses (created_at); CREATE TABLE IF NOT EXISTS waitlist (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, consent_at TEXT NOT NULL, consent_version TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','unsubscribed')));
